var AUDIT={settimana:'18 agosto 2026',visti:30,scartati:'24 letti per esteso e scartati: fuori perimetro (odontoiatria, scoliosi, orecchio, rachide, disco intervertebrale, materiali), scienza di base (biologia cellulare, ingegneria dei materiali), o generici senza termine-nucleo in titolo',nonverificate:['Swissmedic (avvisi dispositivi)','openFDA (tentativo diretto fallito: dominio bloccato dal proxy)','Retraction Watch (archivio salvati vuoto)','pagine ESSKA · AAOS · ICRS','registri protesici (SIRIS · RIPO · NJR · AOANJRR)'],nota:'Giornata di ricerca normale, il giorno dopo il grande recupero del 17 agosto: finestra edat 16-18 agosto. 34 risultati dalla prima interrogazione più 4 dalla seconda (tutti già coincidenti con le schede del 17 agosto, dedup automatico): 30 candidati distinti aperti per esteso, 6 tenuti. Nessuna scheda contraddice oggi una tua tecnica: 0 arancioni è un conteggio, non una rassicurazione.'};
var TENSIONS=[{id:"1",t:"Il rinforzo laterale (LET) su innesto rigido",fai:"Fai il LET su tutti i pazienti che ricostruisci, con innesto di retto femorale.",prove:"Il beneficio del LET è dimostrato su innesto hamstring. Il protocollo STABILITY 2 scrive testualmente che nessuno studio ha stabilito se quel beneficio resta con innesti più rigidi. Aggiornamento del 12 agosto: un database americano su 5.944 gesti combinati conferma che il tempo unico è sicuro — ma non distingue né il costrutto né l'innesto. Nuovo il 17 agosto: il trial GRASE (Copenaghen, 150 pazienti, reclutamento completo) confronterà i tre innesti, quadricipitale compreso — ma senza LET: risponderà sull'innesto, non sulla tua combinazione.",fare:"Non cambiare nulla: non è un errore, è una lacuna della letteratura. Ma se un collega ti chiede perché lo fai su tutti, la risposta onesta è: «beneficio dimostrato su hamstring, esteso per ragionevolezza al quadricipitale».",chiude:"STABILITY 2, braccio quadricipitale con e senza LET, 1292 pazienti. Risultati attesi nel 2029."},{id:"2",t:"Il tuo costrutto non è quello studiato",fai:"Lemaire modificato, fissazione onlay, passaggio superficiale al collaterale laterale.",prove:"I trial usano il passaggio profondo sotto il collaterale e la fissazione con graffa. Sono due costrutti biomeccanicamente diversi, che la letteratura tratta come se fossero la stessa cosa.",fare:"Quando leggi i risultati di un trial sul LET, ricorda che non sono automaticamente i tuoi. Segnale a tuo favore: le note tecniche recenti si stanno spostando verso l'onlay — il campo va dove sei tu, le prove non ancora.",chiude:"Un confronto diretto fra i due costrutti. Oggi non esiste, e nemmeno STABILITY 2 lo risolverà."},{id:"3",t:"Nella radice meniscale conta l'estrusione, non il ritardo",fai:"Rifissazione della radice con tecnica transtibiale. Nel colloquio si tende a pesare il grado condrale e il tempo trascorso dall'infortunio.",prove:"All'analisi multivariata il ritardo NON è predittore indipendente di progressione (p=0,31). Lo sono l'estrusione meniscale (p=0,023) e la larghezza dello spazio articolare preoperatoria. La storia naturale (64 radici non operate, 12 agosto): estrusione da 3,1 a 4,3 mm in 6 mesi mentre il dolore migliora; converte a chirurgia chi ha più varo (soglia HKA 5,5°). E l'osteoporosi più che raddoppia il rischio di frattura subcondrale nella donna (OR 2,29). Lo stato dell'arte J ISAKOS del 17 agosto (Pittsburgh, con Seil, Getgood e Karlsson) conferma la transtibiale come tecnica di scelta e aggiunge il dato che pesa: nel trial sulla centralizzazione l'estrusione aumenta a 6 mesi nel 96,2% delle ginocchia, qualunque cosa si faccia.",fare:"AZIONE CONCRETA, da subito: misura e referta l'estrusione sulla risonanza preoperatoria, e usa quella nel colloquio sul rischio di progressione, al posto del grado condrale e del tempo trascorso. Aggiungi l'asse (varo oltre ~5,5°) e, nella donna, la densità ossea: sono gli altri volti del carico basale.",chiude:"Studi prospettici con l'estrusione come variabile principale. Confidenza attuale: media — due retrospettivi piccoli e ora una coorte prospettica (64 pazienti) nella stessa direzione."},{id:"4",t:"Il criterio di rientro non regge sul tuo innesto",fai:"Se usi la simmetria di forza al 90% come criterio per il ritorno allo sport.",prove:"Sul retto femorale, a 6 mesi, il deficit di estensione è del 29% (simmetria 71%), mentre la flessione recupera al 93%. Con una soglia del 90% quasi nessuno passa a 6 mesi. Aggiornamento del 18 agosto: uno studio trasversale su 30 operati (1-5 anni dall'intervento, tutti gli innesti) conferma che il deficit dell'arto chirurgico nel salto monopodalico resta misurabile anche a distanza di anni (-1,2 cm rispetto al controlaterale; p<0,01); un carico visivo-cognitivo aggiuntivo non lo aggrava ulteriormente rispetto ai controlli sani — il limite sembra dell'arto, non dell'attenzione.",fare:"Verifica che cosa misuri davvero a 6 mesi. Sul quadricipitale aspettati tempi più lunghi per l'estensione: o sposti la scadenza, o cambi la misura. Dato su 31 pazienti, soli maschi, un solo centro.",chiude:"Studi che leghino il deficit di forza a esiti duri (rirottura, mancato rientro) e non a misure intermedie."},{id:"5",t:"Nel minced cartilage varia il tessuto, non solo la tecnica",fai:"Trapianto di cartilagine tritata con filiera dedicata.",prove:"I campioni prelevati da difetti debridati variano oltre dieci volte in peso umido, DNA totale e proteoglicani. Dipende da quale tessuto si raccoglie, non dallo strumento.",fare:"Se un caso va peggio di un altro a parità di gesto chirurgico, la variabile può essere la qualità del tessuto raccolto. Utile saperlo prima di attribuirlo alla tecnica.",chiude:"Una caratterizzazione di vitalità e resa cellulare specifica della filiera che usi. Oggi non esiste."}];
var MUTE={2:"Sulle complicanze femoro-rotulee (RR 1,90; IC 95% 0,63-5,74), la manipolazione in anestesia (RR 0,47; 0,09-2,44) e la revisione (RR 1,96; 0,75-5,14) gli intervalli sono larghi e la certezza è bassa: lo studio non può escludere quasi un raddoppio del rischio di complicanze femoro-rotulee né delle revisioni con l'allineamento cinematico.",3:"Il rischio di revisione (RR 1,32; IC 95% 0,59-2,93) e molte delle differenze funzionali a lungo termine hanno certezza molto bassa: lo studio non può escludere quasi il triplo del rischio di revisione, né confermare con certezza un vantaggio funzionale reale."};
